{
  "understanding": {
    "purpose": "Document the environment variables used to configure document ingestion and explain when and how to set them.",
    "reading": "Readers scan variable names to find a setting, then compare whether it is required, its default, and its description. Each row must remain easy to follow across the table; on a phone, horizontal scrolling can preserve readable values at the cost of hiding later columns initially.",
    "groups": [
      "Name identifies each row and anchors the other values.",
      "Required and Default are compact configuration facts that readers compare across rows.",
      "Description explains the setting and may need substantially more space than the compact fact columns."
    ],
    "keep_intact": [
      "Environment variable names, because they are exact identifiers readers may copy.",
      "Default values and other code-like tokens where possible.",
      "Required values, including longer qualifiers, where practical."
    ],
    "may_wrap": [
      "Description prose can wrap at word boundaries; longer descriptions can use the height already created by wrapping elsewhere in the same row.",
      "Headers and multiword status text can wrap naturally."
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [398, 99, 190, 300],
      "idea": "Preserve all reported unbreakable tokens and give descriptions room to wrap naturally, accepting substantial horizontal scrolling."
    },
    {
      "name": "B",
      "widths": [280, 99, 130, 260],
      "idea": "Reduce scrolling while keeping required values intact and descriptions readable, accepting splits in the longest names and defaults."
    },
    {
      "name": "C",
      "widths": [125, 65, 70, 99],
      "idea": "Fit the entire table within the phone viewport so every field is visible at once, accepting extensive identifier and value splitting and tall rows."
    }
  ]
}
